					LCD_Fill(32,112,32+800,112+48,GRAY_878787); 				// “标题灰条”
					LCD_ShowSpStr(46,118,700,36,WHITE,GRAY_878787,Font_Rbb34,"Reports",0);
					
					LCD_Fill(32,208,32+720,208+48,GRAY_E8E8E8); 			// “中间灰色横条”
					LCD_Fill(32,304,32+720,304+48,GRAY_E8E8E8); 			// “中间灰色横条”
					LCD_Fill(32,400,32+720,400+48,GRAY_E8E8E8); 			// “中间灰色横条”
					LCD_Fill(32,496,32+720,496+48,GRAY_E8E8E8); 			// “中间灰色横条”	

