					// LCD_ShowSpStr(78,317,200,24,BLACK,WHITE,Font_Rbm22,"Actual force:",0);
					// LCD_Fill(78,351,78+256,351+48,GRAY_EDEDED);
					// sprintf(tbuf,"%.1f",AutocalHard);
					// LCD_ShowSpStr(93,362,200,24,GRAY_A6A6A6,GRAY_EDEDED,Font_Rbm22,tbuf,0);
