							LCD_Fill(608+5,438+5,608+256-5,438+60-5,GREEN_3AAA35); 					// OK按钮
							LCD_ShowSpStr(718,455,100,36,WHITE,GREEN_3AAA35,Font_Rbb34,"Ok",0);
