					LCD_ShowIcon(880,112,112,128,BLACK,GRAY_B3B3B3,27,0); 	// Enter
					LCD_ShowSpStr(917,206,60,24,BLACK,GRAY_B3B3B3,Font_Rbm22,"Enter",0);

					LCD_ShowIcon(880,280,112,128,BLACK,WHITE,24,0);
					LCD_ShowSpStr(917,374,100,24,BLACK,WHITE,Font_Rbm22,"Print",0);

