void Touch_Menu(void)
{
	if((cur_tpx > 30)&&(cur_tpx < 30+50)&&(cur_tpy > 30)&&(cur_tpy < 30+50)) 	// “X”图标
	{
		PopWindow = 0;
		cp_flag = 1;
	}
	else
	if((cur_tpx > 150)&&(cur_tpx < 150+64)&&(cur_tpy > 25)&&(cur_tpy < 25+56)) 	// 退出按钮
	{
		LastPage = CurntPage;
		CurntPage = 0;
		PopWindow = 0;
		cp_flag = 1;
	}
	else
	if((cur_tpx > 230)&&(cur_tpx < 230+64)&&(cur_tpy > 20)&&(cur_tpy < 20+64)) 	// “小房子”图标
	{
		LastPage = CurntPage;
		CurntPage = 1;
		PopWindow = 0;
		cp_flag = 1;
	}
	else
	if((cur_tpx > 32)&&(cur_tpx < 32+256)&&(cur_tpy > 103)&&(cur_tpy < 103+70)) 	// 测试报告管理
	{
		if(User_data.Perm_Reports == 1)
		{
			PopWindow = 0; 					// 管理菜单关闭
			LastPage = CurntPage;
			CurntPage = 50; 					// 跳转至Reports
			cp_flag = 1;
		}
		else
			BEEPER_PlayTones(tones_error);
	}
	else
	if((cur_tpx > 32)&&(cur_tpx < 32+256)&&(cur_tpy > 173)&&(cur_tpy < 173+70)) 	// 测试管理
	{
		if(User_data.Perm_TestManage == 1)
		{
			PopWindow = 0; 					// 管理菜单关闭			
			LastPage = CurntPage;
			CurntPage = 130;
			cp_flag = 1;
		}
		else
			BEEPER_PlayTones(tones_error);
	}
	else
	if((cur_tpx > 32)&&(cur_tpx < 32+256)&&(cur_tpy > 243)&&(cur_tpy < 243+70)) 	// Qualification
	{
		if(User_data.Perm_Quali == 1)
		{	
			if(SysInitFlag)
			{							
				PopWindow = 0; 					// 管理菜单关闭			
				LastPage = CurntPage;
				CurntPage = 60; 					// 跳转至Qualification
				cp_flag = 1;
			}
			else
				BEEPER_PlayTones(tones_error);
		}
		else
			BEEPER_PlayTones(tones_error);
	}
	else
	if((cur_tpx > 32)&&(cur_tpx < 32+256)&&(cur_tpy > 313)&&(cur_tpy < 313+70)) 	// 设置管理
	{
		if(User_data.Perm_Admin == 1)
		{
			PopWindow = 0; 					// 管理菜单关闭
			LastPage = CurntPage;
			CurntPage = 80; 					// 跳转至Control Panel
			HotPage = 0;
			cp_flag = 1;
		}
		else
			BEEPER_PlayTones(tones_error);
	}
	else
	if((cur_tpx > 32)&&(cur_tpx < 32+256)&&(cur_tpy > 383)&&(cur_tpy < 383+70)) 	// “用户管理”图标
	{
		if(User_data.Perm_UserManage == 1)
		{
			PopWindow = 0; 					// 管理菜单关闭			
			LastPage = CurntPage;
			CurntPage = 120; 					// 跳转至user management
			cp_flag = 1;
		}
		else
			BEEPER_PlayTones(tones_error);
	}
	else
		BEEPER_PlayTones(tones_error);
}

