// 实时时钟刷新 --------------------------------------------
void RTC_DisRefresh(void)
{
	//RTC_TimeTypeDef RTC_TimeStruct;
	//RTC_DateTypeDef RTC_DateStruct;
	uint8_t Hour,Minute,Day,Month,Year;
	static uint8_t RtcSec;
	
	char tbuf[20];
	
	if(dtFlash == 0) 								// 日期时间刷新
	{
		dtFlash = 250;
		
		// 时间读取 --------------------------------------------
		RTC_GetTime(RTC_Format_BIN, &RTC_TimeStruct);
		if(RtcSec != RTC_TimeStruct.RTC_Seconds)
		{
			RtcSec = RTC_TimeStruct.RTC_Seconds;
			
			sprintf((char*)RealTimeStr,"%02d:%02d",RTC_TimeStruct.RTC_Hours,RTC_TimeStruct.RTC_Minutes); 
			Hour = RTC_TimeStruct.RTC_Hours;
			Minute = RTC_TimeStruct.RTC_Minutes;
			
			// 日期读取 --------------------------------------------
			RTC_GetDate(RTC_Format_BIN, &RTC_DateStruct);
			sprintf((char*)RealDateStr,"%02d.%02d.20%02d",RTC_DateStruct.RTC_Date,RTC_DateStruct.RTC_Month,RTC_DateStruct.RTC_Year); 
			Day = RTC_DateStruct.RTC_Date;
			Month = RTC_DateStruct.RTC_Month;
			Year = RTC_DateStruct.RTC_Year;
			
			// 夏令时调整 ----------------------
			if(CurntPage == 81) 								// Control Panel -> Date and time
			{
				if(tmpPT3 != 0)
					Hour += 1; 
			}
			else
			{
				if(DaylightTime != 0)
					Hour += 1; 
			}
			
			if(Hour > 23)
			{
				Hour = 0;
				Day += 1;
			}
			
			if(Month == 2)
			{
				if((Year ==  0)||(Year ==  4)||(Year ==  8)||(Year == 12)||(Year == 16)||
					 (Year == 20)||(Year == 24)||(Year == 28)||(Year == 32)||(Year == 36)||
					 (Year == 40)||(Year == 44)||(Year == 48)||(Year == 52)||(Year == 56)||
					 (Year == 60)||(Year == 64)||(Year == 68)||(Year == 72)||(Year == 76)||
					 (Year == 80)||(Year == 84)||(Year == 88)||(Year == 92)||(Year == 96))
				{
					if(Day > 29)
					{
						Day = 1;
						Month ++;
					}
				}
				else
				{
					if(Day > 28)
					{
						Day = 1;
						Month ++;
					}
				}
			}
			else
			if((Month == 4)||(Month == 6)||(Month == 9)||(Month == 11)) 	// 小月
			{
				if(Day > 30)
				{
					Day = 1;
					Month ++;
				}
			}
			else 																													// 大月
			{
				if(Day > 31)
				{
					Day = 1;
					Month ++;
				}
			}
			
			if(Month > 12)
			{
				Month = 1;
				Year ++;
			}
			
			sprintf(tbuf,"%02d:%02d",Hour,Minute);
			if(CurntPage == 0)
				LCD_ShowSpStr(60,35,210,24,WHITE,BLACK,24,tbuf,0); 		// 输出时间字符串
			else
				LCD_ShowSpStr(127,35,210,24,WHITE,BLACK,24,tbuf,0); 		// 输出时间字符串
			
			sprintf(DisTimeStr,"%02d:%02d:%02d",Hour,Minute,RtcSec);
			FileTime = ((Year+20)<<25)|(Month<<21)|(Day<<16)|(Hour<<11)|(Minute<<5)|(0x19);		//U盘导出时间保存 2021/11/26 星期五 11:14:54
			// 日期格式调整 --------------------
			if(CurntPage == 81) 								// Control Panel -> Date and time
			{
				if(tmpPT1 == 0)
					sprintf(tbuf,"%02d.%02d.20%02d",Day,Month,Year); 
				else
				if(tmpPT1 == 1)
					sprintf(tbuf,"20%02d-%02d-%02d",Year,Month,Day);
				else
				if(tmpPT1 == 2)
					sprintf(tbuf,"%02d/%02d/20%02d",Month,Day,Year);
			}
			else
			{
				if(DateFormat == 0)
					sprintf(tbuf,"%02d.%02d.20%02d",Day,Month,Year); 
				else
				if(DateFormat == 1)
					sprintf(tbuf,"20%02d-%02d-%02d",Year,Month,Day);
				else
				if(DateFormat == 2)
					sprintf(tbuf,"%02d/%02d/20%02d",Month,Day,Year);
			}
			
			if(CurntPage == 0)
				LCD_ShowSpStr(60,56,250,24,WHITE,BLACK,24,tbuf,0); 		// 输出日期字符串
			else
				LCD_ShowSpStr(127,56,250,24,WHITE,BLACK,24,tbuf,0); 		// 输出日期字符串
			
			strcpy(DisDateStr,tbuf);
		}
	}
}

// 根据年月日返回星期 ---------------------------------------
u8 calcWeekDay(int year, int month,int day)
{
	const int arr[13]={0,0,3,3,6,1,4,6,2,5,0,3,5};
	int calc;
	int weekday;
	
	year %= 400;
	
	if ((year==0||year%4==0&&year%100!=0)&&month<3)
		calc = 5;
	else
		calc = 6;
	
	weekday = (year+year/4-year/100+arr[month]+day+calc)%7;
	
	return (u8)weekday;
}

// 日期时间设置 --------------------------------------------
void RTC_Set(char * DateStr, char * TimeStr) 								// 设置日期和时间
{
	//u16 udat;
	u8 year,month,day,week=0;
	u8 hour,min;
	
	day = (DateStr[0]-0x30)*10 + (DateStr[1]-0x30);
	month = (DateStr[3]-0x30)*10 + (DateStr[4]-0x30);
	year = (DateStr[8]-0x30)*10 + (DateStr[9]-0x30);
	
	hour = (TimeStr[0]-0x30)*10 + (TimeStr[1]-0x30);
	min = (TimeStr[3]-0x30)*10 + (TimeStr[4]-0x30);
	
	RTC_Set_Time(hour,min,0,RTC_H12_AM); 											// 设置时间
	RTC_Set_Date(year,month,day,week); 												// 设置日期
}

// 日期比较 ------------------------------------------------
// d0小于d1，返回-1
// d0等于d1，返回0
// d0大于d1，返回1
int DateComp(RTC_DateTypeDef * d0,RTC_DateTypeDef * d1)
{
	RTC_DateTypeDef date0,date1;
	
	date0 = *d0;
	date1 = *d1;
	
	if(date0.RTC_Year < date1.RTC_Year)
		return -1;
	
	if(date0.RTC_Year > date1.RTC_Year)
		return 1;
	
	if(date0.RTC_Month < date1.RTC_Month)
		return -1;
	
	if(date0.RTC_Month > date1.RTC_Month)
		return 1;
	
	if(date0.RTC_Date < date1.RTC_Date)
		return -1;
	
	if(date0.RTC_Date > date1.RTC_Date)
		return 1;
	
	return 0;
	
}

// 日期累加 ------------------------------------------------
// 把d0+cnt的值放入d1中
void DateAdd(RTC_DateTypeDef * d0,RTC_DateTypeDef * d1,u16 cnt)
{
	u8 Day,Month,Year;
	
	Day 	= d0->RTC_Date;
	Month = d0->RTC_Month;
	Year 	= d0->RTC_Year;
	
	if((Day > 31)||
		 (Month > 12)||
		 (Year > 99))
	{
		*d0 = RTC_DateStruct;
		*d1 = *d0;
		return;
	}
	
	if(cnt > 999)
	{
		*d1 = RTC_DateStruct;
		return;
	}
	
	while(cnt--)
	{
		Day++;
		if(Month == 2)
		{
			if((Year ==  0)||(Year ==  4)||(Year ==  8)||(Year == 12)||(Year == 16)||
				 (Year == 20)||(Year == 24)||(Year == 28)||(Year == 32)||(Year == 36)||
				 (Year == 40)||(Year == 44)||(Year == 48)||(Year == 52)||(Year == 56)||
				 (Year == 60)||(Year == 64)||(Year == 68)||(Year == 72)||(Year == 76)||
				 (Year == 80)||(Year == 84)||(Year == 88)||(Year == 92)||(Year == 96))
			{
				if(Day > 29)
				{
					Day = 1;
					Month++;
				}
			}
			else
			{
				if(Day > 28)
				{
					Day = 1;
					Month++;
				}
			}
		}
		else
		if((Month == 4)||(Month == 6)||(Month == 9)||(Month == 11)) 	// 小月
		{
			if(Day > 30)
			{
				Day = 1;
				Month++;
			}
		}
		else 																													// 大月
		{
			if(Day > 31)
			{
				Day = 1;
				Month++;
			}
		}
		
		if(Month > 12)
		{
			Month = 1;
			Year++;
		}
	}
	
	d1->RTC_Date 	= Day;
	d1->RTC_Month 	= Month;
	d1->RTC_Year 	= Year;
}

// XML文件格式转换 -------------------------------------------------------------
void XmlChange(char *s1, char *s2)
{
	int i,j,len;
	
	len = strlen(s2);
	j = 0;
	for(i=0;i<len;i++)
	{
		s1[j] = s2[i];
		j++;
		if(s2[i] == '&')
		{
			s1[j] = 'a'; j++;
			s1[j] = 'm'; j++;
			s1[j] = 'p'; j++;
			s1[j] = ';'; j++;
		}
	}
	
	s1[j] = 0; 														// 字符串结束符
}

// Can通信数据处理
void CanDataHandle(void)
{
	while(CBRIp0 != CBRIp1) 						// 接收到新数据
	{
		if(CanRxBuf[CBRIp0][0] == 0xA5)
		{
			if((CanRxBuf[CBRIp0][1] == (uint8_t)(12345>>8))&&
					(CanRxBuf[CBRIp0][2] == (uint8_t)(12345&0x00ff)))
			{
				if(CanRxBuf[CBRIp0][3] == 0xA0) 				// 坐标上传信息
				{
					cur_tpx = CanRxBuf[CBRIp0][4];
					cur_tpx <<= 8;
					cur_tpx += CanRxBuf[CBRIp0][5];
					
					cur_tpy = CanRxBuf[CBRIp0][6];
					cur_tpy <<= 8;
					cur_tpy += CanRxBuf[CBRIp0][7];
					
					TouchFlag = 1; 						// 触摸标志				
				}
				else
				if(CanRxBuf[CBRIp0][3] == 0xB0) 				// 触摸板硬件版本号
				{
					TOUCH_HARDWARE_VERSION[0] = CanRxBuf[CBRIp0][4];
					TOUCH_HARDWARE_VERSION[2] = CanRxBuf[CBRIp0][5];
					TOUCH_HARDWARE_VERSION[3] = CanRxBuf[CBRIp0][6];
					TOUCH_HARDWARE_VERSION[5] = CanRxBuf[CBRIp0][7];
				}
				else
				if(CanRxBuf[CBRIp0][3] == 0xB1) 				// 触摸板软件版本号
				{
					TOUCH_FIRMWARE_VERSION[0] = CanRxBuf[CBRIp0][4];
					TOUCH_FIRMWARE_VERSION[1] = CanRxBuf[CBRIp0][5];
					TOUCH_FIRMWARE_VERSION[3] = CanRxBuf[CBRIp0][6];
					TOUCH_FIRMWARE_VERSION[4] = CanRxBuf[CBRIp0][7];
				}
				else
				if(CanRxBuf[CBRIp0][3] == 0x0A) 				// 主板上传指令给液晶屏，液晶屏的应答信息
				{					
					CanTxSn = CanRxBuf[CBRIp0][4];
					
					cp_flag = 1; 													// 刷新页面
					
					if(PopWindow != 0) 										// 有弹出窗口
						PopWflag = 1; 											// 开启刷新标志
					
					if(KeyState != 0) 										// 有键盘窗口显示
					{
						kps_flag = 1; 											// 键盘窗口显示刷新
						kns_flag = 1; 										// 键盘输入内容刷新
					}
				}
			}
		}
		
		CBRIp0++;
		if(CBRIp0 >= 32)
			CBRIp0 = 0;
	}
}

