void setHardUnitFact(u8 unit,float *fact)	// 设置硬度单位
{
	*fact=1.0;
	switch(unit)
	{
		case 0:										//牛顿，N
			*fact=1.0;						
			break;
		case 1:										//公斤，Kp	千克力				
			//*fact=9.81;
			*fact=9.806614;	
			break;
		case 2:									  //？,lbf
			//*fact=4.448;
			*fact=4.44822;
			break;
		case 3:									  //？,Sc
			//*fact=6.874;
			*fact=7.0;
			break;						
	}
}

void setLengthUnitFact(u8 unit,float *fact)		// 设置长度单位
{
	*fact=1.0;
	switch(unit)
	{	
		case 0:										//公制，mm
			*fact=1.0;
			break;
		case 1:										//英制，in
			//*fact=25.4;
			*fact=25.399986;
			break;
	}
}

void setWeightUnitFact(u8 unit,float *fact)		// 设置重量单位
{
	*fact=1.0;
	switch(unit)
	{
		case 0:										//克，g
			*fact=1.0;
			break;
		case 1:										//毫克，mg
			*fact=0.001f;
			break;
	}
}

// 显示整数数字千分位----------------------------------------
void format_with_commas(int num, char *output)
{
    char temp[50];

    sprintf(temp, "%d", num);

    int len = strlen(temp);

    int comma_count = (len - 1) / 3;

    int j = len + comma_count;

    output[j--] = '\0';

    int count = 0;

    for (int i = len - 1; i >= 0; i--)
	{
        if (count == 3) {

            output[j--] = ',';

            count = 0;

        }

        output[j--] = temp[i];

        count++;
    }
}

// 显示浮点数数字千分位----------------------------------------
void format_float_with_commas(double num, char *output)
{
    char temp[50];

    sprintf(temp, "%.2f", num);

    int len = strlen(temp);

    int decimal_point_index = len;

    for (int i = 0; i < len; i++) 
	{
        if (temp[i] == '.') {

            decimal_point_index = i;

            break;
        }
    }

    int comma_count = (decimal_point_index - 1) / 3;

    int j = len + comma_count;

    output[j--] = '\0';

    int count = 0;

    for (int i = len - 1; i >= 0; i--)
	{
        if (i < decimal_point_index && count == 3) {

            output[j--] = ',';

            count = 0;
        }

        output[j--] = temp[i];

        count++;
    }
}

// 长度调整
void AdjLength(float nomilength)
{
	int smot = 0;
	motor_error = 0;
	NomiLength = nomilength;
	
	if(dmmess())
	{
		motor_moveTo(-blops,(FastMoveSP/2)*51200);
		do
		{
			step = (int)readMotDat(TMC5160_XACTUAL, &MotSpiStatus);
		}while(step != (-blops));

		return;
	}

	FalSize = NomiLength*0.5f;
	step = (int)(FalSize*mmfactor);
	motor_moveTo(-step,51200*(DiaMeasSpeed/2));

	while(abs(Get_ADC_AvrgNum(AverNum)-nullwert) < NwtFak*ContactForce)
	{
		smot = (int)readMotDat(TMC5160_XACTUAL, &MotSpiStatus);
		if(smot == (-step))
		{
			motor_error = 2;
			break;
		}
	}						

	motor_stop();
	if(motor_error == 0)
	{
		oldmmfactor = mmfactor;
		LengthValue = abs((int)readMotDat(TMC5160_XACTUAL, &MotSpiStatus))/mmfactor;
		//LengthValue += 0.00f;

		mmfactor *= (LengthValue/NomiLength);
	}

	osDelay(50);
	motor_moveTo(-blops,(FastMoveSP/2)*51200);
	do
	{
		step = (int)readMotDat(TMC5160_XACTUAL, &MotSpiStatus);
	}while(step != (-blops));
	
	if(motor_error == 0)
	{
		if(LongTabhold)
			LengthValue += 30.0f;

		CurntPage = 70;
		cp_flag = 1;						
	}
}

// (直接/一般数据)测试封装功能 ------------------------------------------------------
// mode: 0：测量长度  1：测量硬度
float MeasureLength(float nomilength)
{
	int smot = 0;
	motor_error = 0;
	NomiLength = nomilength;

	// 前往名义尺寸+偏移尺寸位置
	if(dmmess())
	{
		motor_moveTo(-blops,(FastMoveSP/2)*51200);
		do
		{
			step = (int)readMotDat(TMC5160_XACTUAL, &MotSpiStatus);
		}while(step != (-blops));
		motor_error = 1;
		return(0);
	}
	
	// 前往失效尺寸位置
	FalSize = NomiLength*0.5f;
	step = (int)(FalSize*mmfactor);
	motor_moveTo(-step,51200*(DiaMeasSpeed/2));

	while(abs(Get_ADC_AvrgNum(AverNum)-nullwert) < NwtFak*ContactForce)
	{
		smot = (int)readMotDat(TMC5160_XACTUAL, &MotSpiStatus);
		if(smot == (-step))
		{
			motor_error = 2;
			break;
		}
		
		if((CurntPage == 6 || CurntPage == 25) && ConLidSensor == 1)
		{
			if(GetIni(1) == 0)
			{
				motor_stop();
				while(GetIni(1) == 0);
				PauseFlag = 1;
				motor_error = 2;
				break;
			}
		}

		// CAN通信处理 -------------------------------
		CanDataHandle();

		if(TouchFlag == 1) 							// 有触摸标志
		{
			TouchFlag = 0;
			BEEPER_PlayTones(tones_1khz);
			AbortHandle();
		}
	}

	motor_stop();
	LengthValue = abs((int)readMotDat(TMC5160_XACTUAL, &MotSpiStatus))/mmfactor;
	//LengthValue += 0.00f;

	if(motor_error != 0)
		LengthValue = 0;

	// 回到原点位置
	osDelay(50);
	motor_moveTo(-blops,(FastMoveSP/2)*51200);
	do
	{
		if(ConLidSensor == 1 && GetIni(1) == 0 && CurntPage != 108)
		{
			motor_stop();
			while(GetIni(1) == 0);
			PauseFlag = 2;
			motor_moveTo(-blops,(FastMoveSP/2)*51200);
		}
		step = (int)readMotDat(TMC5160_XACTUAL, &MotSpiStatus);

		// CAN通信处理 -------------------------------
		CanDataHandle();

		if(TouchFlag == 1) 							// 有触摸标志
		{
			TouchFlag = 0;
			BEEPER_PlayTones(tones_1khz);
			AbortHandle();
		}

	}while(step != (-blops));

	return(LengthValue);
}
// 测量硬度
float MeasureHard(float nomilength)
{
	int smot = 0;
	int ueberl=0;
	int uebverg;
	int maxmew = 0;
	int maxval;
	int adx = 0;
	int adxx = 0;
	int abfval;	
	motor_error = 0;
	EncoderErr = 0;

	NomiLength = nomilength;
	if(dmmess())
	{
		motor_moveTo(-blops,(FastMoveSP/2)*51200);
		do
		{
			step = (int)readMotDat(TMC5160_XACTUAL, &MotSpiStatus);
		}while(step != (-blops));
		motor_error = 1;
		LengthValue = 0;
		return(0);
	}

	FalSize = NomiLength*0.5f;
	step = (int)(FalSize*mmfactor);
	motor_moveTo(-step,51200*(DiaMeasSpeed/2));

	while(abs(Get_ADC_AvrgNum(AverNum)-nullwert) < NwtFak*Sensitivity)
	{
		smot = (int)readMotDat(TMC5160_XACTUAL, &MotSpiStatus);
		if(smot == (-step))
		{
			motor_error = 2;			
			LengthValue = 0;
			Hardness = 0;
			break;			
		}
		
		if((CurntPage == 6 || CurntPage == 25) && ConLidSensor == 1)
		{
			if(GetIni(1) == 0)
			{
				motor_stop();
				while(GetIni(1) == 0);
				PauseFlag = 1;
				motor_error = 2;
				break;
			}
		}

		// CAN通信处理 -------------------------------
		CanDataHandle();

		if(TouchFlag == 1) 							// 有触摸标志
		{
			TouchFlag = 0;
			BEEPER_PlayTones(tones_1khz);
			AbortHandle();
		}
	}
	
	motor_stop();

	if(motor_error == 0)
	{
		LengthValue = abs((int)readMotDat(TMC5160_XACTUAL, &MotSpiStatus))/mmfactor;

		ForceAdx0 = ForceAdx1 = 0; 					// 推力寄存器复位
		ForceStep = MeaForce*NwtFak; 				// 恒力参数转换
		ForceStep = ForceStep/100; 			// 每10毫秒应达到的力(100Hz)				

		maxval = ForceLimit*NwtFak;
		abfval = NwtFak*Sensitivity/2;
		ueberl = 0;
		maxmew = 0;

		if(MeasureMeth==0) 									// 恒速测量
		{
			uebverg=40;
			motor_moveTo(-step,51200*(MeaSpeed/2));
		}	
		else 												// 恒力测量
		{
			uebverg=40*2;
		}

		// ueberl恒速：40；恒力：80；
		while(ueberl<uebverg && maxmew<maxval)
		{
			adx = abs(ADC_Num()-nullwert);
			if(adx>maxmew)
			{
				maxmew=adx;
			}

			smot = (int)readMotDat(TMC5160_XACTUAL, &MotSpiStatus);

			EncoderErr = Encoder_deviation_detected();
			if(EncoderErr)
			{
				motor_stop();
				return 0;
			}

			if(smot >= (-step))
			{
				maxmew = 0;
				break;
			}

			if(MeasureMeth == 1)
			{
				if(mesenable == 1)
				{
					mesenable = 0;
					motor_moveTo(-step,51200*(0.5f/2));	// 
					ForceAdx0 += ForceStep;
				}
				ForceAdx1 = adx - ForceAdx0; 									// 当前推力差 = 当前推力-上一次推力
				if(ForceAdx1 >= ForceStep) 										// 当前推力差 >= 恒力参数设定值（转换过）
				{
					motor_stop();									// 1秒内推力上限已经到达标志，电机停转						
				}
			}

			// 盖子打开处理
			if(ConLidSensor == 1 && GetIni(1) == 0)
			{
				motor_stop();
				step = (int)readMotDat(TMC5160_XACTUAL, &MotSpiStatus);
				osDelay(50);
				motor_moveTo(step-(1.0f*mmfactor),(2.3/2)*51200);
				while(GetIni(1) == 0);
				PauseFlag = 3;

				motor_moveTo(-blops,(FastMoveSP/2)*51200);
				do
				{
					step = (int)readMotDat(TMC5160_XACTUAL, &MotSpiStatus);
				}while(step != (-blops));
				
				return(0);
			}

			// 触摸动作处理 -------------------------------
			CanDataHandle();
			if(TouchFlag == 1) 							// 有触摸标志
			{
				TouchFlag = 0;
				BEEPER_PlayTones(tones_1khz);
				AbortHandle();
			}

			// 破碎判断？---------------------------------
			adxx=maxmew-abfval;
			if(adxx<0)
				adxx=0;
			if(adx<adxx)
			{
				ueberl++;
			}
			else
			{
				ueberl=0;
			}
		}

		motor_stop();
		Hardness = maxmew/NwtFak;
	}

	osDelay(50);
	motor_moveTo(-blops,(FastMoveSP/2)*51200);
	do
	{
		if(ConLidSensor == 1 && GetIni(1) == 0)
		{
			motor_stop();
			while(GetIni(1) == 0);
			PauseFlag = 2;
			motor_moveTo(-blops,(FastMoveSP/2)*51200);
		}
		step = (int)readMotDat(TMC5160_XACTUAL, &MotSpiStatus);

		EncoderErr = Encoder_deviation_detected();
		if(EncoderErr)
		{
			motor_stop();
			return 0;
		}

		// CAN通信处理 -------------------------------
		CanDataHandle();

		if(TouchFlag == 1) 							// 有触摸标志
		{
			TouchFlag = 0;
			BEEPER_PlayTones(tones_1khz);
			AbortHandle();
		}

	}while(step != (-blops));

	return(Hardness);
}

