// 控制电机达到名义硬度的位置
void mekabef(void)
{
	int smot = 0;
	int maxmew = 0;
	int maxval;
	int adx = 0;

	if(dmmess())
	{
		return;
	}

	FalSize = NomiLength*0.5f;
	step = (int)(FalSize*mmfactor);
	motor_moveTo(-step,51200*(DiaMeasSpeed/2));

	while(abs(Get_ADC_AvrgNum(AverNum)-nullwert) < NwtFak*Sensitivity)
	{
		smot = (int)readMotDat(TMC5160_XACTUAL, &MotSpiStatus);
		if(smot == (-step))
		{
			return;
		}
	}
	
	motor_stop();

	ForceAdx0 = ForceAdx1 = 0; 					// 推力寄存器复位
	ForceStep = 50*NwtFak; 				// 恒力参数转换
	ForceStep = ForceStep/100; 			// 每10毫秒应达到的力(100Hz)

	maxval = ForceLimit*NwtFak;
	maxmew = 0;

	while(maxmew<maxval)
	{
		adx = abs(ADC_Num()-nullwert);
		if(adx>maxmew)
		{
			maxmew=adx;
		}

		if(mesenable == 1)
		{
			mesenable = 0;
			motor_moveTo(-step,51200*(0.5f/2));	// 

			ForceAdx0 += ForceStep;
		}
		ForceAdx1 = adx - ForceAdx0; 									// 当前推力差 = 当前推力-上一次推力
		if(ForceAdx1 >= ForceStep) 										// 当前推力差 >= 恒力参数设定值（转换过）
		{
			motor_stop();									// 1秒内推力上限已经到达标志，电机停转						
		}
	}
	motor_stop();	
}

// 根据测量数据组计算需要的结果 ------------------------------------------------
void calcauswert(void)
{
	int i=0;
	unsigned int testnum=0;
	double messwd=0,messwh=0,messwt=0,messww=0,messwz=0;

	double xqsumh=0,xqsumd=0,xqsumt=0,xqsumw=0,xqsumz=0;	// 平方累加和
	double sumd=0,sumh=0,sumt=0,sumw=0,sumz=0;	// 累加和
	double varia=0;	// 方差

	minh=10000.0; 													// 硬度最小值
	mind=1000.0; 													// 直径最小值
	mint=1000.0; 													// 厚度最小值
	minw=1000.0;													// 宽度最小值
	minz=120000.0;													// 重量最小值
	
	maxh=0.0; 														// 硬度最大值
	maxd=0.0; 														// 直径最大值
	maxt=0.0; 														// 厚度最大值
	maxw=0.0;// 宽度最大值
	maxz=0.0;// 重量最大值

	max_minh=0.0;	// 硬度最大最小差值
	max_mind=0.0;
	max_mint=0.0;
	max_minw=0.0;
	max_minz=0.0;

	mittd=0.0;		// 直径平均值
	mitth=0.0; 		// 硬度平均值
	mittt=0.0; 		// 厚度平均值
	mittw=0.0;		// 宽度平均值
	mittz=0.0;		// 重量平均值

	xqsumh=0.0; 													// 测量结果的平方累加和
	xqsumd=0.0;
	xqsumt=0.0;
	xqsumw=0.0;
	xqsumz=0.0;

	sreld=0.0; 														// 直径偏差率
	srelh=0.0; 														// 硬度偏差率
	srelt=0.0; 														// 厚度偏差率
	srelw=0.0;// 宽度偏差率
	srelz=0.0;// 重量偏差率
	
	sabwh=0.0; 														// 硬度标准偏差
	sabwd=0.0; 														// 直径标准偏差
	sabwt=0.0; 														// 厚度标准偏差
	sabww=0.0;// 宽度标准偏差
	sabwz=0.0;// 重量标准偏差
	
	auswanzh=0; 													// 硬度有效测试次数
	auswanzd=0; 													// 直径有效测试次数
	auswanzt=0; 													// 厚度有效测试次数
	auswanzw=0;// 宽度有效测试次数
	auswanzz=0;// 重量有效测试次数
	
	testnum=CurRN;

	if(HardUnit == 0)
		limit = Rp_rsmp.RPT_ForceLimit;
	else
		limit = round2(Rp_rsmp.RPT_ForceLimit/HardFact);
	
	for(i=0;i<testnum;i++) 								// 测试次数？，Gavin，2020-01-09 星期四 11:36:12
	{
		if((Rp_rsmp.RPT_Tolerance_All[i] == 0 && Rp_rsmp.RPT_Type == 5) || Rp_rsmp.RPT_Type == 4)
		{
			messwh = (double)meHard[i]; 					// 硬度，按单位取值

			messwd = (double)meDiam[i]; 					// 直径，按单位取值
			messwt = (double)meThick[i]; 					// 厚度，按单位取值
			messww = (double)meWidth[i];					// 宽度，按单位取值

			messwz = (double)meWeight[i];					// 重量，按单位取值
			
			// 按要求取小数点后几位 --------------------------------
			if(LengthUnit==0) 		// 长度单位 毫米 ##.##
			{
				messwd=round2d(messwd);
				messwt=round2d(messwt);
				messww=round2d(messww);
			}
			else 					// 英寸 #.####
			{
				messwd=round4d(messwd);
				messwt=round4d(messwt);
				messww=round4d(messww);
			}
			
			if(HardUnit==0) 		// 硬度单位 牛顿 ###.#
			{
				messwh=round1d(messwh);
				cam1 = round0(meHard[i]*10);
				cam2 = round0(limit*10);
			}
			else					// 千克力KP ###.##	SC ###.##	lbf ###.##
			{
				messwh=round2d(messwh);
				cam1 = round0(meHard[i]*100);
				cam2 = round0(limit*100);
			}

			if(WeightUnit==0) 		// 重量单位 克 ###.#####
				messwz=round4d(messwz);
			else					// 毫克 ###.#
				messwz=round1d(messwz);

			if(((int)meHard[i] < 99999) && (cam1 < cam2)) 								// 硬度统计计算
			{
				if(messwh>maxh) maxh = messwh; 		// 计算最大值
				if(messwh<minh) minh = messwh; 		// 计算最小值
				
				sumh += messwh; 									// 计算测量结果的累加和
				xqsumh += messwh*messwh; 				// 计算测量结果的平方累加和
				auswanzh++; 												// 计算测量次数
			}
			
			if((int)meDiam[i] < 99999) 								// 直径统计计算
			{
				if(messwd>maxd) maxd = messwd; 	// 计算最大值
				if(messwd<mind) mind = messwd; 	// 计算最小值
				
				sumd += messwd; 								// 计算测量结果的累加和
				xqsumd += messwd*messwd; 			// 计算测量结果的平方累加和
				auswanzd++; 										// 计算测量次数
			}
			
			if((int)meThick[i] < 99999) 								// 厚度统计计算
			{
				if(messwt>maxt) maxt = messwt; 	// 计算最大值
				if(messwt<mint) mint = messwt; 	// 计算最小值
				
				sumt += messwt; 								// 计算测量结果的累加和
				xqsumt += messwt*messwt; 			// 计算测量结果的平方累加和
				auswanzt++; 										// 计算测量次数
			}

			if((int)meWidth[i] < 99999) 								// 宽度统计计算
			{
				if(messww>maxw) maxw = messww; 	// 计算最大值
				if(messww<minw) minw = messww; 	// 计算最小值
				
				sumw += messww; 								// 计算测量结果的累加和

				xqsumw += messww*messww; 			// 计算测量结果的平方累加和
				auswanzw++; 										// 计算测量次数
			}

			if((int)meWeight[i] < 199999) 								// 重量统计计算
			{
				if(messwz>maxz) maxz = messwz; 	// 计算最大值
				if(messwz<minz) minz = messwz; 	// 计算最小值
				
				sumz += messwz; 								// 计算测量结果的累加和
				xqsumz += messwz*messwz; 			// 计算测量结果的平方累加和
				auswanzz++; 										// 计算测量次数
			}
		}				
	}
	
	// 硬度，标准偏差计算，平均值计算，偏差率计算 ------------
	if(auswanzh>=1) 
	{
		max_minh = maxh - minh;
		// 计算标准偏差（算法已经验证过，与(((x1-xp)^2+(x2-xp)^2+...+(xn-xp)^2))/(n-1))^(1/2)相同) -------
		varia=(xqsumh-(sumh * sumh/(double)auswanzh))/((double)auswanzh-1.0);
		
		sabwh=sqrt(varia); 								// 开根号
		if(sabwh < 0.0000001f)
			sabwh=0.0;
		
		// 计算平均值 --------------------------------
		mitth=sumh/(double)auswanzh;
		
		if(mitth>0.0f)
		{
			if(HardUnit==0) 										// 硬度单位
			{
				sabwh = round1(sabwh);
				mitth = round1(mitth);
			}
			else
			{
				sabwh = round2(sabwh);
				mitth = round2(mitth);
			}
			srelh = round2((sabwh/mitth)*100.0f);
		}
	}
	else 
	{
		if(auswanzh==0)
			minh=0; 
	}
	
	// 直径，标准偏差计算，平均值计算，偏差率计算 ------------
	if(auswanzd>=1) 
	{
		max_mind = maxd - mind;
		// 计算标准偏差（算法已经验证过，与(((x1-xp)^2+(x2-xp)^2+...+(xn-xp)^2))/(n-1))^(1/2)相同) -------
		varia=(xqsumd-(sumd * sumd/(double)auswanzd))/((double)auswanzd-1.0);
		
		sabwd=sqrt(varia);
		if(sabwd < 0.0000001f)
			sabwd=0.0;
		
		// 计算平均值 --------------------
		mittd=sumd/(double)auswanzd;
		
		if(mittd>0.0f)
		{
			if(LengthUnit==0) 											// 长度单位
			{
				sabwd = round2(sabwd);
				mittd = round2(mittd);
			}
			else
			{
				sabwd = round4(sabwd);
				mittd = round4(mittd);
			}
			
			sreld = round2((sabwd/mittd)*100.0f);
		}
	}
	else 
	{
		if(auswanzd==0)
			mind=0; 
	}
	
	// 厚度，标准偏差计算，平均值计算，偏差率计算 ------------
	if(auswanzt>=1) 
	{
		max_mint = maxt - mint;		
		// 计算标准偏差（算法已经验证过，与(((x1-xp)^2+(x2-xp)^2+...+(xn-xp)^2))/(n-1))^(1/2)相同) -------
		varia=(xqsumt-(sumt * sumt/(double)auswanzt))/((double)auswanzt-1.0);
		
		sabwt=sqrt(varia);
		if(sabwt < 0.0000001f)
			sabwt=0.0;
		
		// 计算平均值 ------------------------------
		mittt=sumt/(double)auswanzt;
		
		if(mittt>0.0f)
		{
			if(LengthUnit==0) 											// 长度单位
			{
				sabwt = round2(sabwt);
				mittt = round2(mittt);
			}
			else
			{
				sabwt = round4(sabwt);
				mittt = round4(mittt);
			}
			
			srelt = round2((sabwt/mittt)*100.0f);
		}
	}
	else 
	{
		if(auswanzt==0)
			mint=0; 
	}

	// 宽度，标准偏差计算，平均值计算，偏差率计算 ------------
	if(auswanzw>=1) 
	{
		max_minw = maxw - minw;
		// 计算标准偏差（算法已经验证过，与(((x1-xp)^2+(x2-xp)^2+...+(xn-xp)^2))/(n-1))^(1/2)相同) -------
		varia=(xqsumw-(sumw * sumw/(double)auswanzw))/((double)auswanzw-1.0);
		
		sabww=sqrt(varia);
		if(sabww < 0.0000001f)
			sabww=0.0;
		
		// 计算平均值 ------------------------------
		mittw = sumw/(double)auswanzw;
		
		if(mittw>0.0f)
		{
			if(LengthUnit==0) 											// 长度单位
			{
				sabww = round2(sabww);
				mittw = round2(mittw);
			}
			else
			{
				sabww = round4(sabww);
				mittw = round4(mittw);
			}
			
			srelw = round2((sabww/mittw)*100.0f);
		}
	}
	else 
	{
		if(auswanzw==0)
			minw=0; 
	}

	// 重量，标准偏差计算，平均值计算，偏差率计算 ------------
	if(auswanzz>=1) 
	{
		max_minz = maxz-minz;
		// 计算标准偏差（算法已经验证过，与(((x1-xp)^2+(x2-xp)^2+...+(xn-xp)^2))/(n-1))^(1/2)相同) -------
		varia=(xqsumz-(sumz * sumz/(double)auswanzz))/((double)auswanzz-1.0);
		
		sabwz=sqrt(varia);
		if(sabwz < 0.0000001f)
			sabwz=0.0;
		
		// 计算平均值 ------------------------------
		mittz=sumz/(double)auswanzz;
		
		if(mittz>0.0f)
		{
			if(WeightUnit==0) 											// 重量单位
			{
				sabwz = round4(sabwz);
				mittz = round4(mittz);
			}
			else
			{
				sabwz = round1(sabwz);
				mittz = round1(mittz);
			}
			
			srelz = round2((sabwz/mittz)*100.0f);
		}
	}
	else 
	{
		if(auswanzz==0)
			minz=0;
	}
}

// 公差结果计算
// 参数：data：测量值	nominal：名义值		mode：公差索引 0-4 weight,thick,width,diam,hard
// 返回值：计算结果
u8 ToleranceJudge(float data, float nominal, u8 index)
{
	u8 result;	// 0:default 1:T1 2:T2 3:T3 4:Min-Max 5:PL 6:FM
	int diff=0;
	int expand=0;
	int T1L=0,T1R=0,T2L=0,T2R=0,T3L=0,T3R=0,MML=0,MMR=0,PLL=0,PLR=0;

	if(index==0)
	{
		if(WeightUnit)
			expand = 10;
		else
			expand = 10000;
	}
	else
	if(index==1 || index==2 || index==3)
	{
		if(LengthUnit)
			expand = 10000;
		else
			expand = 100;
	}
	else
	{
		if(HardUnit == 0)
			expand = 10;
		else
			expand = 100;
	}

	diff = round0(data*expand);

	if(Meth_data.MM_Deviation == 0)	// 绝对值
	{
		T1L = round0((nominal-Meth_data.MM_T1_Left[index])*expand);
		T1R = round0((nominal+Meth_data.MM_T1_Right[index])*expand);
		T2L = round0((nominal-Meth_data.MM_T2_Left[index])*expand);
		T2R = round0((nominal+Meth_data.MM_T2_Right[index])*expand);
		T3L = round0((nominal-Meth_data.MM_T3_Left[index])*expand);
		T3R = round0((nominal+Meth_data.MM_T3_Right[index])*expand);
		MML = round0((nominal-Meth_data.MM_MinMax_Left[index])*expand);
		MMR = round0((nominal+Meth_data.MM_MinMax_Right[index])*expand);
		PLL = round0((nominal-Meth_data.MM_PL_Left[index])*expand);
		PLR = round0((nominal+Meth_data.MM_PL_Right[index])*expand);
	}
	else	// 相对值
	{
		T1L = round0((1-Meth_data.MM_T1_Left[index]/100)*nominal*expand);
		T1R = round0((1+Meth_data.MM_T1_Right[index]/100)*nominal*expand);
		T2L = round0((1-Meth_data.MM_T2_Left[index]/100)*nominal*expand);
		T2R = round0((1+Meth_data.MM_T2_Right[index]/100)*nominal*expand);
		T3L = round0((1-Meth_data.MM_T3_Left[index]/100)*nominal*expand);
		T3R = round0((1+Meth_data.MM_T3_Right[index]/100)*nominal*expand);
		MML = round0((1-Meth_data.MM_MinMax_Left[index]/100)*nominal*expand);
		MMR = round0((1+Meth_data.MM_MinMax_Right[index]/100)*nominal*expand);
		PLL = round0((1-Meth_data.MM_PL_Left[index]/100)*nominal*expand);
		PLR = round0((1+Meth_data.MM_PL_Right[index]/100)*nominal*expand);
	}

	if(Meth_data.MM_ToleranceRule == 0)		// T1 T2 T3/PL
	{
		if(diff>=T1L && diff<=T1R)
			result = 1;
		else
		if(diff>=T2L && diff<=T2R)
			result = 2;
		else
		if(diff>=T3L && diff<=T3R)
			result = 3;
		else
			result = 6;
	}
	else
	{
		if(diff>=MML && diff<=MMR)
			result = 4;
		else
		if(diff>=PLL && diff<=PLR)
			result = 5;
		else
			result = 6;
	}

	return result;
}

// 公差结果计算
// 参数：data：测量值	nominal：名义值		mode：公差索引 0-4 weight,thick,width,diam,hard
// 返回值：计算结果
u8 ToleranceJudgeAve(float data, float average, float nominal, u8 index)
{
	u8 result;	// 0:default 1:T1 2:T2 3:T3 4:Min-Max 5:PL 6:FM
	int diff=0;
	int expand=0;
	int T1L=0,T1R=0,T2L=0,T2R=0,T3L=0,T3R=0,MML=0,MMR=0,PLL=0,PLR=0;

	if(index==0)
	{
		if(WeightUnit)
			expand = 10;
		else
			expand = 10000;
	}
	else
	if(index==1 || index==2 || index==3)
	{
		if(LengthUnit)
			expand = 10000;
		else
			expand = 100;
	}
	else
	{
		if(HardUnit == 0)
			expand = 10;
		else
			expand = 100;
	}

	diff = round0(data*expand);

	if(Meth_data.MM_Deviation == 0)	// 绝对值
	{
		T1L = round0((average-Meth_data.MM_T1_Left[index])*expand);
		T1R = round0((average+Meth_data.MM_T1_Right[index])*expand);
		T2L = round0((average-Meth_data.MM_T2_Left[index])*expand);
		T2R = round0((average+Meth_data.MM_T2_Right[index])*expand);
		T3L = round0((nominal-Meth_data.MM_T3_Left[index])*expand);
		T3R = round0((nominal+Meth_data.MM_T3_Right[index])*expand);
		MML = round0((average-Meth_data.MM_MinMax_Left[index])*expand);
		MMR = round0((average+Meth_data.MM_MinMax_Right[index])*expand);
		PLL = round0((nominal-Meth_data.MM_PL_Left[index])*expand);
		PLR = round0((nominal+Meth_data.MM_PL_Right[index])*expand);
	}
	else	// 相对值
	{
		T1L = round0((1-Meth_data.MM_T1_Left[index]/100)*average*expand);
		T1R = round0((1+Meth_data.MM_T1_Right[index]/100)*average*expand);
		T2L = round0((1-Meth_data.MM_T2_Left[index]/100)*average*expand);
		T2R = round0((1+Meth_data.MM_T2_Right[index]/100)*average*expand);
		T3L = round0((1-Meth_data.MM_T3_Left[index]/100)*nominal*expand);
		T3R = round0((1+Meth_data.MM_T3_Right[index]/100)*nominal*expand);
		MML = round0((1-Meth_data.MM_MinMax_Left[index]/100)*average*expand);
		MMR = round0((1+Meth_data.MM_MinMax_Right[index]/100)*average*expand);
		PLL = round0((1-Meth_data.MM_PL_Left[index]/100)*nominal*expand);
		PLR = round0((1+Meth_data.MM_PL_Right[index]/100)*nominal*expand);
	}

	if(Meth_data.MM_ToleranceRule == 0)		// T1 T2 T3/PL
	{
		if(diff>=T1L && diff<=T1R)
			result = 1;
		else
		if(diff>=T2L && diff<=T2R)
			result = 2;
		else
		if(diff>=T3L && diff<=T3R)
			result = 3;
		else
			result = 6;
	}
	else
	{
		if(diff>=MML && diff<=MMR)
			result = 4;
		else
		if(diff>=PLL && diff<=PLR)
			result = 5;
		else
			result = 6;
	}

	return result;
}

// 获取电子秤稳定读数
float GetWeight(void)
{
	EBalanceTxCnt = 0;
	EBalanceRxCnt = 0;
	u8 BalanceSteady = 0;	// 电子秤读数稳定标志
	WeightFlag = 1;
	u8 NotSteadyCount = 0;

	while(BalanceSteady == 0 && NotSteadyCount < 7)
	{
		if(flash_flag)
		{
			if(WeightFlag)
			{
				WeightFlag = 0;
				
				if(BalanceModel == 1) 			// Sartorius Practum
					Balance_SendString("\x1b\x20\x6b\x50\x5f"); 			// "ESC kP_"，询问重量
				else
				if(BalanceModel == 2) 			// Mettler Me 54
					Balance_SendString("\x53\x0d\x0a"); 							// "S"，询问重量
	
				EBalanceTxCnt++;
				osDelay(100);
			}
		}
		else 
		{
			WeightFlag = 1;
			if(EBalanceTxCnt >= 3)
			{
				if(EBalanceTxCnt == EBalanceRxCnt)	// 读数稳定
				{
					BalanceSteady = 1;
				}
				else	// 读数不稳定，需要重新读
				{
					EBalanceTxCnt = 0;
					EBalanceRxCnt = 0;
					NotSteadyCount++;
				}
			}
		}

		CanDataHandle();
		if(TouchFlag)
		{
			TouchFlag = 0;
			BEEPER_PlayTones(tones_1khz);
			AbortHandle();
			if(TestAbortFlag == 1)
				return 0;
		}		
	}

	if(NotSteadyCount >= 7)
		return 0;
	else
		return BalanceWeight;
}

unsigned int GetIni(unsigned int num)
{
	unsigned int i;

	switch(num)
	{
		case 1:
			
			i=Get_Adc(ADC_Channel_10) & 0x03FF;		// PC0
			break;
		case 2:
			i=Get_Adc(ADC_Channel_11) & 0x03FF;		// PC1
			break;
		case 3:
			i =0;
			break;
		case 4:
			i =0;
			break;
		default:
			i=0;
			break;
	}
	
	if(i>850) return(1);
	
	return(0);
}

u16 Get_Adc(u8 ch)
{
	  	//设置指定ADC的规则组通道,一个序列,采样时间
	ADC_RegularChannelConfig(ADC1, ch, 1, ADC_SampleTime_480Cycles );	//ADC1,ADC通道,480个周期,提高采样时间可以提高精准度	    
  
	ADC_SoftwareStartConv(ADC1);		//使能指定的ADC1的软件转换启动功能	
	 
	while(!ADC_GetFlagStatus(ADC1, ADC_FLAG_EOC ));//等待转换结束

	return ADC_GetConversionValue(ADC1);	//返回最近一次ADC1规则组的转换结果
}

u8 BalanceInit(void)
{
	EBalanceTxCnt = 0;
	EBalanceRxCnt = 0;
	u8 BalanceSteady = 0;	// 电子秤读数稳定标志
	WeightFlag = 1;
	u8 NotSteadyCount = 0;

	while(BalanceSteady == 0 && NotSteadyCount < 5)
	{
		if(flash_flag)
		{
			if(WeightFlag)
			{
				WeightFlag = 0;
				
				if(BalanceModel == 1) 			// Sartorius Practum
					Balance_SendString("\x1b\x20\x6b\x50\x5f"); 			// "ESC kP_"，询问重量
				else
				if(BalanceModel == 2) 			// Mettler Me 54
					Balance_SendString("\x53\x0d\x0a"); 							// "S"，询问重量
	
				EBalanceTxCnt++;
				osDelay(100);
			}
		}
		else 
		{
			WeightFlag = 1;
			if(EBalanceTxCnt >= 3)
			{
				if(EBalanceTxCnt == EBalanceRxCnt)	// 读数稳定
				{
					BalanceSteady = 1;
				}
				else	// 读数不稳定，需要重新读
				{
					EBalanceTxCnt = 0;
					EBalanceRxCnt = 0;
					NotSteadyCount++;
				}
			}
		}

		CanDataHandle();
		if(TouchFlag)
		{
			TouchFlag = 0;
			BEEPER_PlayTones(tones_1khz);

			if((cur_tpx > 880)&&(cur_tpx < 880+112)&&(cur_tpy > 448)&&(cur_tpy < 448+128))
			{
				InitResult = 6;	// 用户中止初始化流程
				return 0;
			}
			else
				BEEPER_PlayTones(tones_error);
		}
	}

	if(NotSteadyCount >= 5)
		return 0;
	else
		return 1;
}

void WeiCheReportSave(void)
{
	// 报告数据保存 ----------------------------------------
	Reports_CalAdj.RPT_Status = CaliStatus;
	Reports_CalAdj.RPT_Type = 7; 						// 重量校正

	AdjReportNum++;
	Reports_CalAdj.RPT_AdjReportNum = AdjReportNum;		// ID
	writinteep(AdjReportNum,ADRAdjReportNum);

	strcpy(Reports_CalAdj.RPT_LoginName,User_data.UD_Username);
	Reports_CalAdj.RPT_UserID = User_data.UD_FixedUserID;
	strcpy(Reports_CalAdj.RPT_FirstName,User_data.UD_FirstName);
	strcpy(Reports_CalAdj.RPT_LastName,User_data.UD_LastName);

	RTC_GetTime(RTC_Format_BIN, &RTC_TimeStruct);
	RTC_GetDate(RTC_Format_BIN, &RTC_DateStruct);
	Reports_CalAdj.RPT_Date = RTC_DateStruct; 				// 校正结束日期
	Reports_CalAdj.RPT_Time = RTC_TimeStruct; 				// 校正结束时间

	NewDate.QUAL_Date = RTC_DateStruct; 				// 测试日期
	NewDate.QUAL_Time = RTC_TimeStruct; 				// 测试时间
	strcpy(NewDate.QUAL_TimeZone,TimeZoneList[TimeZone][0]); 			// 时区字符串
	readeepbuf((unsigned char *)&LastDate, ADRWeiCalDate, sizeof(QUAL_ST));
	writeepbuf((unsigned char *)&NewDate, ADRWeiCalDate, sizeof(QUAL_ST));

	Reports_CalAdj.RPT_Tolerance = WeightTole;		// 校正公差

	for(u8 i=0;i<5;i++)
	{
		Reports_CalAdj.RPT_SetValue[i] = SetValue[i];
		Reports_CalAdj.RPT_ActValue[i] = ActValue[i];
		Reports_CalAdj.RPT_Result[i] = CaliResult[i];
	}

	strcpy(Reports_CalAdj.RPT_DeviceSerialNb, DeviceSerialNb); 					// 设备序列号
	strcpy(Reports_CalAdj.RPT_MbVersion, MAIN_FIRMWARE_VERSION); 			// 主控板版本号
	strcpy(Reports_CalAdj.RPT_DbVersion, TOUCH_FIRMWARE_VERSION); 			// 显示板版本号

	memcpy(Reports_CalAdj.RPT_TimeZone,TimeZoneList[TimeZone][0]+3,3);

	if(OQ_PtGp.OQ_sw == 0 && PQ_PtGp.OQ_sw == 0)
		strcpy(Reports_CalAdj.RPT_OQ,"-");
	else
	{
		if((DateComp(&RTC_DateStruct,&OQ_PtGp.OQ_EON_dst) == 1 && OQ_PtGp.OQ_sw == 1) || (DateComp(&RTC_DateStruct,&PQ_PtGp.OQ_EON_dst) == 1 && PQ_PtGp.OQ_sw == 1))
			strcpy(Reports_CalAdj.RPT_OQ,"NO");
		else
			strcpy(Reports_CalAdj.RPT_OQ,"YES");
	}

	// 保存报告内容
	W25QXX_Write((unsigned char *)&Reports_CalAdj,ADR_WeiCALI_REPORTS01+(WeigCalRptIp*4096),REPORT_CALI_LONG);
	osDelay(100);

	// 报告指针+1
	WeigCalRptIp++;
	if(WeigCalRptIp >= CALI_REPORT_MAX)
	WeigCalRptIp = 0;
	writeeeprom(WeigCalRptIp, ADR_WeigCalRptIp);
}

